const key="worldforge-prototype-v1";const defaults={explorerName:"Explorer",theme:"dark",journeys:[],collections:{library:[],museum:[],workshop:[]}};let data=(()=>{try{const s=JSON.parse(localStorage.getItem(key));return{...defaults,...s,collections:{...defaults.collections,...(s?.collections||{})}}}catch{return structuredClone(defaults)}})();const esc=s=>String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[c]));function save(){localStorage.setItem(key,JSON.stringify(data));render()}function render(){document.body.classList.toggle("light",data.theme==="light");themeButton.textContent=data.theme==="light"?"Change Dark":"Change Light";welcomeName.textContent=data.explorerName;explorerName.value=data.explorerName==="Explorer"?"":data.explorerName;libraryCount.textContent=`${data.collections.library.length} items`;museumCount.textContent=`${data.collections.museum.length} items`;workshopCount.textContent=`${data.collections.workshop.length} projects`;journeyCount.textContent=`${data.journeys.length} entries`;journeyList.innerHTML=data.journeys.map((x,i)=>`<article class="list-item"><button class="delete" data-j="${i}">Delete</button><strong>${esc(x.text)}</strong><br><small>${esc(x.date)}</small></article>`).join("")||"<p>No journey entries yet.</p>";for(const k of["library","museum","workshop"]){document.querySelector(`[data-list="${k}"]`).innerHTML=data.collections[k].map((x,i)=>`<article class="list-item"><button class="delete" data-k="${k}" data-i="${i}">Delete</button><strong>${esc(x.title)}</strong><p>${esc(x.notes||"No notes yet.")}</p></article>`).join("")||"<p>Nothing has been added yet.</p>"}}document.querySelectorAll(".world-nav button").forEach(b=>b.onclick=()=>{document.querySelectorAll(".world-nav button").forEach(x=>x.classList.remove("active"));document.querySelectorAll(".view").forEach(x=>x.classList.remove("active-view"));b.classList.add("active");document.getElementById(b.dataset.view).classList.add("active-view")});themeButton.onclick=()=>{data.theme=data.theme==="dark"?"light":"dark";save()};profileForm.onsubmit=e=>{e.preventDefault();data.explorerName=explorerName.value.trim()||"Explorer";save()};journeyForm.onsubmit=e=>{e.preventDefault();const t=journeyText.value.trim();if(t){data.journeys.unshift({text:t,date:new Date().toLocaleString()});journeyText.value="";save()}};document.querySelectorAll(".collection-form").forEach(f=>f.onsubmit=e=>{e.preventDefault();const d=new FormData(f),k=f.dataset.kind,t=String(d.get("title")||"").trim();if(t){data.collections[k].unshift({title:t,notes:String(d.get("notes")||"").trim()});f.reset();save()}});document.onclick=e=>{if(e.target.dataset.j!==undefined){data.journeys.splice(Number(e.target.dataset.j),1);save()}if(e.target.dataset.k){data.collections[e.target.dataset.k].splice(Number(e.target.dataset.i),1);save()}};const skills=["Literature & Writing","Mathematics","Science","Computer Science & AI","Carpentry","Electrical","Plumbing","Welding","Automotive","Medicine & Nursing","Agriculture","Environmental Stewardship","Music & Theater","Visual Art & Design","Business & Logistics","Cooking & Home Skills","Government & Law","Teaching & Mentoring"];skillGrid.innerHTML=skills.map(s=>`<article class="card"><h3>${esc(s)}</h3><p>Every skill is relevant. Every skill has value.</p></article>`).join("");render();
